      std::printf("    recess: %zu faces, closed %d, panel at y %.3f\n", m.face_count(), (int)closed_manifold(m), ymin_top);
      CHECK(closed_manifold(m) && std::fabs(ymin_top - 0.3f) < 1e-3f);
      ed.command("hs recess 0.1 -0.2");  // a raised plate
