    std::printf("    during the drag: image %d wide, a new snapshot each frame %s; after %d\n", w1, v1 != v2 ? "yes" : "no", after);
    CHECK(w1 == 256);
    CHECK(g2 != g1 && v1 != v2);
    CHECK(after == 1024);
