    const float tip_err = length(b1->world_matrix().point({0, b1->get<Bone>()->length, 0}) - target->world_position());
    std::printf("    IK added by a click: the tip off its moved target by %g\n", tip_err);
    CHECK(tip_err < 1e-3f);
