    /* The arm bone stops above the hand: the hand's vertices are nearer the leg bone, through the leg's surface. */
    const std::vector<BoneSegment> bones{{"Leg", {0, 0, 0}, {0, 1, 0}}, {"Arm", {0.22f, 1.2f, 0}, {0.22f, 0.7f, 0}}};
    std::vector<float> e;
