    for (size_t v = leg_n; v < m.vert_count(); v++)
      if (m.positions[v].y < 0.6f) skinweights::envelope_weights(m.positions[v], bones, e), env_hand = std::max(env_hand, e[0]);
    InpaintReport rep;
    std::string err;
    CHECK(automatic_skin_weights(m, bones, InpaintOptions{}, &rep, &err));
    float hand = 0.0f;
